// rangeReaderStubReadRangeArgs returns the samples of the arguments of
// ReadRange.
func rangeReaderStubReadRangeArgs(tb assert.TB) (context.Context, string, int64, []byte, version.Version) {
	tb.Helper()
	a0 := assert.Context(tb)
	var a1 string
	var a2 int64
	var a3 []byte
	var a4 version.Version
	a1 = "ReadRange-a"
	a2 = 42
	a3 = []byte{1}
	a4 = version.Version("")
	return a0, a1, a2, a3, a4
}

// rangeReaderStubReadRange calls ReadRange of s with the samples of its
// arguments.
func rangeReaderStubReadRange(tb assert.TB, s *blobtest.RangeReaderStub) (int, blob.Info, error) {
	tb.Helper()
	a0, a1, a2, a3, a4 := rangeReaderStubReadRangeArgs(tb)
	return s.ReadRange(a0, a1, a2, a3, a4)
}

// rangeReaderStubReadRangePins returns the samples of the results of
// ReadRange, with a new error as its error result.
func rangeReaderStubReadRangePins() (int, blob.Info, error) {
	var want0 int
	var want1 blob.Info
	want2 := errors.New("ReadRange-returns")
	want0 = 42
	want1 = blob.Info{Key: "Key-a"}
	return want0, want1, want2
}

// rangeReaderStubReadRangeSubject returns the subject of [stub.Behaviour]
// for ReadRange. The subject calls a new double that reports to tb.
func rangeReaderStubReadRangeSubject(
	tb assert.TB,
) stub.Subject[blobtest.RangeReaderReadRangeCall, blobtest.RangeReaderReadRangeReturn] {
	tb.Helper()
	s := blobtest.NewRangeReaderStub(tb)
	return stub.Subject[blobtest.RangeReaderReadRangeCall, blobtest.RangeReaderReadRangeReturn]{
		Stub: s.OnReadRange.MethodStub,
		Call: func() {
			_, _, _ = rangeReaderStubReadRange(tb, s)
		},
		Result: func() blobtest.RangeReaderReadRangeReturn {
			got0, got1, got2 := rangeReaderStubReadRange(tb, s)
			return blobtest.RangeReaderReadRangeReturn{Result0: got0, Result1: got1, Err: got2}
		},
		Override: func(mark func()) {
			s.OnReadRange.Func(
				func(_ context.Context, _ string, _ int64, _ []byte, _ version.Version) (int, blob.Info, error) {
					mark()
					var z0 int
					var z1 blob.Info
					var z2 error
					return z0, z1, z2
				},
			)
		},
		Fails: func() error {
			_, _, r2 := rangeReaderStubReadRange(tb, s)
			return r2
		},
	}
}

// rangeReaderStubInstance is the instance of a blobtest.RangeReaderStub
// that the checks of the constructors and the options drive.
type rangeReaderStubInstance = stub.Instance[blobtest.RangeReaderReadRangeCall]

// rangeReaderStubInstanceOf returns the instance of s. The options apply
// to the whole double, so the checks call ReadRange alone.
func rangeReaderStubInstanceOf(tb assert.TB, s *blobtest.RangeReaderStub) rangeReaderStubInstance {
	tb.Helper()
	return rangeReaderStubInstance{
		Stub: s.OnReadRange.MethodStub,
		Call: func() {
			_, _, _ = rangeReaderStubReadRange(tb, s)
		},
		Reset: s.ResetCalls,
	}
}

// TestRangeReaderStub checks the methods, the constructors and the options
// of the double RangeReaderStub.
func TestRangeReaderStub(t *testing.T) {
	t.Parallel()

	t.Run("ReadRange", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "ReadRange", rangeReaderStubReadRangeSubject)

		t.Run("records the arguments of the call", func(t *testing.T) {
			t.Parallel()
			s := blobtest.NewRangeReaderStub(t)
			_, _, _ = rangeReaderStubReadRange(t, s)
			got := s.OnReadRange.AssertCalledOnce(t, "ReadRange records the call")
			a0, a1, a2, a3, a4 := rangeReaderStubReadRangeArgs(t)
			expect.Equal(t, got.Ctx, a0, "the call records Ctx", expect.ByIdentity())
			expect.Equal(t, got.Key, a1, "the call records Key")
			expect.Equal(t, got.Off, a2, "the call records Off")
			expect.Equal(t, got.Dst, a3, "the call records Dst")
			expect.Equal(t, got.IfMatch, a4, "the call records IfMatch")
		})

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := blobtest.NewRangeReaderStub(t)
			var seen []blobtest.RangeReaderReadRangeCall
			s.OnReadRange.OnRecord(func(c blobtest.RangeReaderReadRangeCall) { seen = append(seen, c) })
			_, _, _ = rangeReaderStubReadRange(t, s)
			_, _, _ = rangeReaderStubReadRange(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of ReadRange")
		})
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()
		stub.ResetBehaviour(t, func(tb assert.TB) rangeReaderStubInstance {
			return rangeReaderStubInstanceOf(tb, blobtest.NewRangeReaderStub(tb))
		})

		t.Run("clears the recorded calls of ReadRange", func(t *testing.T) {
			t.Parallel()
			s := blobtest.NewRangeReaderStub(t)
			_, _, _ = rangeReaderStubReadRange(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnReadRange.CallCount(), 0, "ResetCalls clears the calls of ReadRange")
		})

		t.Run("keeps the results of Returns of ReadRange", func(t *testing.T) {
			t.Parallel()
			s := blobtest.NewRangeReaderStub(t)
			want0, want1, want2 := rangeReaderStubReadRangePins()
			s.OnReadRange.Returns(want0, want1, want2)
			s.ResetCalls()
			got0, got1, got2 := rangeReaderStubReadRange(t, s)
			expect.Equal(t, got0, want0, "ResetCalls keeps the Result0 of ReadRange")
			expect.Equal(t, got1, want1, "ResetCalls keeps the Result1 of ReadRange")
			expect.ErrorIs(t, got2, want2, "ResetCalls keeps the error of ReadRange")
		})
	})

	t.Run("NewRangeReaderStubDelayed", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) rangeReaderStubInstance {
			return rangeReaderStubInstanceOf(tb, blobtest.NewRangeReaderStubDelayed(tb, d, clk))
		})
	})

	t.Run("NewRangeReaderStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails ReadRange with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("ReadRange-failing")
			s := blobtest.NewRangeReaderStubFailing(t, want)
			_, _, r2 := rangeReaderStubReadRange(t, s)
			assert.ErrorIs(t, r2, want, "ReadRange fails with the error of NewRangeReaderStubFailing")
		})
	})

	t.Run("RangeReaderStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) rangeReaderStubInstance {
			return rangeReaderStubInstanceOf(tb, blobtest.NewRangeReaderStub(tb, blobtest.RangeReaderStubStrict()))
		})
	})

	t.Run("RangeReaderStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes ReadRange to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := blobtest.NewRangeReaderStub(t)
			s := blobtest.NewRangeReaderStub(t, blobtest.RangeReaderStubDelegateTo(inner))
			_, _, _ = rangeReaderStubReadRange(t, s)
			inner.OnReadRange.AssertCalledOnce(t, "ReadRange calls the implementation")
		})

		t.Run("fails ReadRange with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("ReadRange-delegate")
			inner := blobtest.NewRangeReaderStub(t)
			inner.OnReadRange.Faults(want, 1)
			s := blobtest.NewRangeReaderStub(t, blobtest.RangeReaderStubDelegateTo(inner))
			_, _, r2 := rangeReaderStubReadRange(t, s)
			assert.ErrorIs(t, r2, want, "ReadRange fails with the error of the implementation")
		})
	})

	t.Run("RangeReaderStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) rangeReaderStubInstance {
			return rangeReaderStubInstanceOf(
				tb,
				blobtest.NewRangeReaderStub(tb, blobtest.RangeReaderStubWithClock(clk)),
			)
		})
	})

	t.Run("RangeReaderStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) rangeReaderStubInstance {
			return rangeReaderStubInstanceOf(
				tb,
				blobtest.NewRangeReaderStub(tb, blobtest.RangeReaderStubWithRandSource(src)),
			)
		})
	})

	t.Run("RangeReaderStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) rangeReaderStubInstance {
			return rangeReaderStubInstanceOf(tb, blobtest.NewRangeReaderStub(tb, blobtest.RangeReaderStubBenchMode()))
		})
	})

	t.Run("RangeReaderStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) rangeReaderStubInstance {
			return rangeReaderStubInstanceOf(
				tb,
				blobtest.NewRangeReaderStub(
					tb,
					blobtest.RangeReaderStubWithClock(clk),
					blobtest.RangeReaderStubWithLatency(d),
				),
			)
		})
	})

	t.Run("RangeReaderStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails ReadRange with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("ReadRange-failing")
			s := blobtest.NewRangeReaderStub(t, blobtest.RangeReaderStubFailing(want))
			_, _, r2 := rangeReaderStubReadRange(t, s)
			assert.ErrorIs(t, r2, want, "ReadRange fails with the error of RangeReaderStubFailing")
		})
	})

	t.Run("WithRangeReaderReadRange", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of ReadRange", func(t *testing.T) {
			t.Parallel()
			called := false
			s := blobtest.NewRangeReaderStub(
				t,
				blobtest.WithRangeReaderReadRange(
					func(_ context.Context, _ string, _ int64, _ []byte, _ version.Version) (int, blob.Info, error) {
						called = true
						var z0 int
						var z1 blob.Info
						var z2 error
						return z0, z1, z2
					},
				),
			)
			_, _, _ = rangeReaderStubReadRange(t, s)
			assert.True(t, called, "WithRangeReaderReadRange sets the function of ReadRange")
		})
	})
}

// TestRangeReaderReadRangeStub checks the methods of
// RangeReaderReadRangeStub, which configures ReadRange.
func TestRangeReaderReadRangeStub(t *testing.T) {
	t.Parallel()

	t.Run("Returns", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the results of each call of ReadRange", func(t *testing.T) {
			t.Parallel()
			s := blobtest.NewRangeReaderStub(t)
			want0, want1, want2 := rangeReaderStubReadRangePins()
			s.OnReadRange.Returns(want0, want1, want2)
			got0, got1, got2 := rangeReaderStubReadRange(t, s)
			expect.Equal(t, got0, want0, "ReadRange returns the Result0 that Returns sets")
			expect.Equal(t, got1, want1, "ReadRange returns the Result1 that Returns sets")
			expect.ErrorIs(t, got2, want2, "ReadRange returns the error that Returns sets")
		})

		t.Run("configures ReadRange for strict mode", func(t *testing.T) {
			t.Parallel()
			r := assert.NewRecorder()
			s := blobtest.NewRangeReaderStub(r)
			s.OnReadRange.Strict()
			var want0 int
			var want1 blob.Info
			var want2 error
			s.OnReadRange.Returns(want0, want1, want2)
			_, _, _ = rangeReaderStubReadRange(t, s)
			assert.False(t, r.Failed(), "strict mode accepts the call of ReadRange")
		})
	})

	t.Run("Func", func(t *testing.T) {
		t.Parallel()

		t.Run("passes the arguments of each call of ReadRange to the function", func(t *testing.T) {
			t.Parallel()
			s := blobtest.NewRangeReaderStub(t)
			var got0 context.Context
			var got1 string
			var got2 int64
			var got3 []byte
			var got4 version.Version
			s.OnReadRange.Func(
				func(p0 context.Context, p1 string, p2 int64, p3 []byte, p4 version.Version) (int, blob.Info, error) {
					got0, got1, got2, got3, got4 = p0, p1, p2, p3, p4
					var z0 int
					var z1 blob.Info
					var z2 error
					return z0, z1, z2
				},
			)
			_, _, _ = rangeReaderStubReadRange(t, s)
			a0, a1, a2, a3, a4 := rangeReaderStubReadRangeArgs(t)
			expect.Equal(t, got0, a0, "the function receives Ctx", expect.ByIdentity())
			expect.Equal(t, got1, a1, "the function receives Key")
			expect.Equal(t, got2, a2, "the function receives Off")
			expect.Equal(t, got3, a3, "the function receives Dst")
			expect.Equal(t, got4, a4, "the function receives IfMatch")
		})
	})
}

